const form=document.querySelector('#auth-form'),status=document.querySelector('.auth-status');
const fromLink=new URLSearchParams(location.search).get('verified')==='1';
form.elements.email.value=sessionStorage.getItem('uniify-reset-email')||'';
if(fromLink){form.elements.code.required=false;form.elements.code.closest('.auth-field').hidden=true;form.elements.email.required=false;form.elements.email.closest('.auth-field').hidden=true;}
form.onsubmit=async event=>{event.preventDefault();const button=form.querySelector('[type=submit]');button.disabled=true;status.hidden=false;try{const data=Object.fromEntries(new FormData(form));if(fromLink){delete data.email;delete data.code;}const response=await fetch('/api/auth/reset-password',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const result=await response.json();if(!response.ok)throw Error(result.error||'Unable to reset your password.');sessionStorage.removeItem('uniify-reset-email');form.reset();status.textContent='Password updated. You can now sign in.';}catch(error){status.textContent=error.message;}finally{form.elements.password.value='';button.disabled=false;status.focus();}};
